{
  "name": "ESP32-CAM相机模块",
  "name_en": "ESP32-CAM camera module",
  "manufacturer": "",
  "description": "一种基于 ESP32 的嵌入式网络相机模块，通常集成图像传感器、Wi‑Fi 通信和板载补光 LED，可通过网络获取单帧图像或视频流，并调节增益、曝光和分辨率。适用于实验中的低成本远程观察、样品监看、简单机器视觉与成像记录。",
  "description_en": "An embedded network camera module based on the ESP32, typically integrating an image sensor, Wi‑Fi connectivity, and an onboard illumination LED. It can deliver single images or video streams over the network and supports adjustment of gain, exposure, and frame size. It is suitable for low-cost remote observation, sample monitoring, simple machine vision, and imaging documentation in laboratory setups.",
  "tag_hints": [
    "ESP32-CAM",
    "Wi-Fi camera",
    "embedded imaging",
    "MJPEG streaming",
    "LED illumination",
    "exposure control",
    "gain control",
    "remote sample monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-base_uri",
      "description": "获取相机的网络基地址。",
      "description_en": "Get the camera's network base URI."
    },
    {
      "action_name": "auto-get_json",
      "description": "从相机的指定网络接口读取 JSON 信息。",
      "description_en": "Read JSON data from a specified camera network endpoint."
    },
    {
      "action_name": "auto-post_json",
      "description": "向相机的指定网络接口发送 JSON 命令或参数。",
      "description_en": "Send a JSON command or parameters to a specified camera network endpoint."
    },
    {
      "action_name": "auto-post",
      "description": "向相机的指定网络接口发送 POST 请求。",
      "description_en": "Send a POST request to a specified camera network endpoint."
    },
    {
      "action_name": "auto-setLed",
      "description": "设置板载 LED 补光强度。",
      "description_en": "Set the onboard LED illumination intensity."
    },
    {
      "action_name": "auto-set_id",
      "description": "设置设备标识编号。",
      "description_en": "Set the device identification number."
    },
    {
      "action_name": "auto-setGain",
      "description": "设置图像采集增益。",
      "description_en": "Set the image acquisition gain."
    },
    {
      "action_name": "auto-setExposureTime",
      "description": "设置图像曝光时间。",
      "description_en": "Set the image exposure time."
    },
    {
      "action_name": "auto-setFrameSize",
      "description": "设置图像帧尺寸或分辨率。",
      "description_en": "Set the image frame size or resolution."
    },
    {
      "action_name": "auto-get_id",
      "description": "获取设备标识编号。",
      "description_en": "Get the device identification number."
    },
    {
      "action_name": "auto-is_omniscope",
      "description": "检查设备是否处于 OmniScope 相关模式或标识。",
      "description_en": "Check whether the device reports an OmniScope-related mode or identity."
    },
    {
      "action_name": "auto-restart",
      "description": "重启相机模块。",
      "description_en": "Restart the camera module."
    },
    {
      "action_name": "auto-start_stream",
      "description": "启动实时图像流传输。",
      "description_en": "Start real-time image streaming."
    },
    {
      "action_name": "auto-stop_stream",
      "description": "停止实时图像流传输。",
      "description_en": "Stop real-time image streaming."
    },
    {
      "action_name": "auto-getframe",
      "description": "获取单帧图像。",
      "description_en": "Acquire a single image frame."
    },
    {
      "action_name": "auto-getframes",
      "description": "从指定视频流地址连续读取图像帧。",
      "description_en": "Continuously read image frames from a specified stream URL."
    },
    {
      "action_name": "auto-soft_trigger",
      "description": "执行软件触发采集。",
      "description_en": "Perform a software-triggered acquisition."
    }
  ]
}

